<?php $badge = function ($s) { include APP_ROOT . '/views/partials/status.php'; }; ?>
<div class="topbar"><h1>Action center</h1><div class="row"><?php foreach (['pending', 'approved', 'rejected', 'changes_requested'] as $s): ?><a class="btn btn-sm <?= $status === $s ? 'btn-dark' : 'btn-ghost' ?>" href="?status=<?= $s ?>"><?= e(label($s)) ?></a><?php endforeach; ?></div></div>
<?php if (!$rows): ?><div class="empty">Nothing here.</div><?php endif; ?>
<?php foreach ($rows as $a): $d = jdec($a['details']); $pl = jdec($a['payload'], null); ?>
<div class="panel"><div class="row spread"><div><h2 style="margin:0"><?= e($a['title']) ?></h2><span class="small muted">#<?= (int)$a['id'] ?> · <?= e(label($a['kind'])) ?> · requested by <?= e($a['requested_by']) ?> · <?= e($a['created_at']) ?> UTC</span></div><div class="row"><?php $badge($a['risk']); $badge($a['status']); ?></div></div>
  <div class="grid g2" style="margin-top:12px"><div class="small"><?php foreach (['what' => 'What the AI wants to do', 'why' => 'Why', 'expected' => 'Expected result', 'risks' => 'Risks', 'cost' => 'Cost', 'impact' => 'Customer impact', 'evidence' => 'Evidence'] as $k => $l): if (!empty($d[$k])): ?><p><b><?= $l ?>:</b> <?= e($d[$k]) ?></p><?php endif; endforeach; ?>
    <?php if ($a['subject_type']): ?><p class="muted">Subject: <?= e($a['subject_type']) ?> #<?= e($a['subject_id']) ?><?php if ($a['subject_type'] === 'agent_task'): ?> — <a href="/admin/tasks/<?= (int)$a['subject_id'] ?>">open task</a><?php elseif ($a['subject_type'] === 'project'): $pn = App\Db::val('SELECT number FROM projects WHERE id = ?', [$a['subject_id']]); ?> — <a href="/admin/projects/<?= e($pn) ?>">open project</a><?php elseif ($a['subject_type'] === 'order'): $on = App\Db::val('SELECT number FROM orders WHERE id = ?', [$a['subject_id']]); ?> — <a href="/admin/orders/<?= e($on) ?>">open order</a><?php endif; ?></p><?php endif; ?></div>
  <div><?php if ($pl && !empty($pl['tool'])): ?><p class="small"><b>Proposed action:</b> <span class="kbd"><?= e($pl['tool']) ?></span> by <?= e($pl['agent']) ?></p><?php endif; ?>
    <?php if ($a['status'] === 'pending'): ?><form method="post" action="/admin/approvals/<?= (int)$a['id'] ?>" class="stack"><?= App\Csrf::field() ?>
      <?php if ($pl && !empty($pl['tool'])): ?><label class="small" for="mi<?= (int)$a['id'] ?>">Modify input (JSON, optional)</label><textarea id="mi<?= (int)$a['id'] ?>" name="modified_input" style="font-family:var(--mono);font-size:.8rem;min-height:90px"><?= e(json_encode($pl['input'], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)) ?></textarea><?php endif; ?>
      <textarea name="note" placeholder="Note for the record or instructions for the agent (optional)" style="min-height:60px"></textarea>
      <div class="row"><button class="btn btn-success btn-sm" name="decision" value="approve">Approve</button><button class="btn btn-ghost btn-sm" name="decision" value="request_info">Request more info</button><button class="btn btn-danger btn-sm" name="decision" value="reject">Reject</button></div></form>
    <?php else: ?><p class="small">Decided by <?= e($a['decided_by']) ?> at <?= e($a['decided_at']) ?>. <?= e($a['decision_note']) ?></p><?php endif; ?></div></div></div>
<?php endforeach; ?>
